theorem MeasureTheory.extracted_1.{u_1} {α : Type u_1} [inst : MeasurableSpace α] {μ : Measure α} {s : Set α}
  (hs : MeasurableSet s) (f g : α → ℝ≥0∞) [inst_1 : (j : α) → Decidable (j ∈ s)] :
  ∫⁻ (x : α) in s, s.piecewise f g x ∂μ = ∫⁻ (a : α) in s, f a ∂μ := sorry

theorem MeasureTheory.extracted_1.{u_1} {α : Type u_1} [inst : MeasurableSpace α] {μ : Measure α} {s : Set α}
  (hs : MeasurableSet s) (f g : α → ℝ≥0∞) [inst_1 : (j : α) → Decidable (j ∈ s)] :
  ∫⁻ (x : α) in sᶜ, s.piecewise f g x ∂μ = ∫⁻ (a : α) in sᶜ, g a ∂μ := sorry

theorem MeasureTheory.extracted_1.{u_1} {α : Type u_1} [inst : MeasurableSpace α] {μ : Measure α} {s : Set α}
  {f : α → ℝ≥0∞} (hs : μ sᶜ = 0) (hf : ∀ x ∈ s, f x = 0) (hmes : MeasurableSet s) :
  ∫⁻ (x : α) in s, 0 ∂μ + 0 = 0 := sorry

theorem MeasureTheory.extracted_1.{u_1} {α : Type u_1} [inst : MeasurableSpace α] {μ : Measure α} {s : Set α}
  {f : α → ℝ≥0∞} (hs : μ sᶜ = 0) (hf : ∀ x ∈ s, f x = 0) (hmes : MeasurableSet s) :
  ∀ᵐ (x : α) ∂μ, x ∈ s → f x = 0 := sorry
